from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import letter
from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
from reportlab.lib.units import inch
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak

OUT = "output/pdf/vendor_master_interface_implementation_meeting_notes.pdf"
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name="TitleBlue", parent=styles["Title"], fontName="Helvetica-Bold", fontSize=23, leading=28, textColor=colors.HexColor("#123B5D"), alignment=TA_LEFT, spaceAfter=10))
styles.add(ParagraphStyle(name="H1Blue", parent=styles["Heading1"], fontName="Helvetica-Bold", fontSize=15, leading=19, textColor=colors.HexColor("#123B5D"), spaceBefore=11, spaceAfter=6))
styles.add(ParagraphStyle(name="H2Blue", parent=styles["Heading2"], fontName="Helvetica-Bold", fontSize=10.5, leading=13, textColor=colors.HexColor("#1E6388"), spaceBefore=8, spaceAfter=4))
styles.add(ParagraphStyle(name="Body", parent=styles["BodyText"], fontName="Helvetica", fontSize=9, leading=12.3, spaceAfter=5))
styles.add(ParagraphStyle(name="Small", parent=styles["BodyText"], fontName="Helvetica", fontSize=7.6, leading=9.5))
styles.add(ParagraphStyle(name="Head", parent=styles["BodyText"], fontName="Helvetica-Bold", fontSize=7.6, leading=9.5, textColor=colors.white))
styles.add(ParagraphStyle(name="Risk", parent=styles["BodyText"], fontName="Helvetica-Bold", fontSize=9, leading=12, textColor=colors.HexColor("#9C2D1D")))

def p(txt, sty="Body"):
    return Paragraph(txt, styles[sty])

def tbl(headers, rows, widths, highlight=None):
    data = [[p(x, "Head") for x in headers]] + [[p(str(x), "Small") for x in row] for row in rows]
    t = Table(data, colWidths=widths, repeatRows=1, hAlign="LEFT")
    commands = [("BACKGROUND",(0,0),(-1,0),colors.HexColor("#123B5D")), ("GRID",(0,0),(-1,-1),0.28,colors.HexColor("#B8C9D3")), ("VALIGN",(0,0),(-1,-1),"TOP"), ("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F2F7FA")]), ("LEFTPADDING",(0,0),(-1,-1),5), ("RIGHTPADDING",(0,0),(-1,-1),5), ("TOPPADDING",(0,0),(-1,-1),4), ("BOTTOMPADDING",(0,0),(-1,-1),4)]
    if highlight:
        commands += [("BACKGROUND", (0,highlight), (-1,highlight), colors.HexColor("#FFF1D9"))]
    t.setStyle(TableStyle(commands)); return t

def foot(canvas, doc):
    canvas.saveState(); canvas.setStrokeColor(colors.HexColor("#D5E0E6")); canvas.line(.55*inch,.48*inch,7.95*inch,.48*inch)
    canvas.setFont("Helvetica",7.4); canvas.setFillColor(colors.HexColor("#51616E")); canvas.drawString(.55*inch,.30*inch,"Sample Implementation Meeting Notes - Vendor Master Interface"); canvas.drawRightString(7.95*inch,.30*inch,"Page %s" % doc.page); canvas.restoreState()

doc = SimpleDocTemplate(OUT, pagesize=letter, leftMargin=.55*inch, rightMargin=.55*inch, topMargin=.55*inch, bottomMargin=.68*inch)
s=[]
s += [p("IMPLEMENTATION MEETING NOTES", "Small"), Spacer(1,.08*inch), p("Vendor Master Interface\nRequirements Review", "TitleBlue"), p("Legacy Procurement Hub to SAP S/4HANA | Meeting record and decision log", "Body"), Spacer(1,.18*inch)]
s.append(tbl(["Meeting attribute", "Detail"], [["Meeting date", "18 October 2026"], ["Meeting type", "Functional design workshop"], ["Document reference", "FS-INT-VM-001, Vendor Master Interface Functional Specification v1.0 (sample)"], ["Facilitator", "SAP Functional Lead"], ["Status", "Open decision required - requirement conflict identified"]], [1.55*inch,5.45*inch]))
s += [Spacer(1,.18*inch), p("Attendees", "H1Blue"), tbl(["Role", "Organization", "Participation"], [["Procurement Process Owner", "Client", "Business requirement owner"], ["Vendor Master Data Lead", "Client", "Data policy owner"], ["AP Manager", "Client", "Finance stakeholder"], ["SAP Functional Lead", "Implementation Partner", "Facilitator"], ["Integration Lead", "Implementation Partner", "Interface design owner"], ["Security and Controls Lead", "Implementation Partner", "Control reviewer"]], [2.1*inch,2.0*inch,2.9*inch])]
s += [p("Meeting Objective", "H1Blue"), p("Confirm scope, data-selection rules, and validation behavior for the inbound vendor master interface before finalizing functional specification FS-INT-VM-001.")]
s += [p("Executive Summary", "H1Blue"), p("The client requested that blocked vendors be excluded from all outbound vendor-master messages to SAP S/4HANA. During review, the team identified a conflict with the current functional specification: BR-01 requires a supplier account group/category for every create, while the proposed exclusion rule assumes blocked vendor status can be evaluated before the target supplier category is derived. The current source payload does not require the blocked status indicator as a mandatory field, so SAP cannot consistently enforce or audit the requested exclusion.", "Body"), p("Decision: No final decision was reached. The issue is recorded as a design blocker pending confirmation of the authoritative blocked-vendor status, field mandatory rule, and treatment of already-replicated blocked vendors.", "Risk"), PageBreak()]

s += [p("Discussion Notes", "H1Blue"), tbl(["Topic", "Notes / agreement"], [["Client request", "The client stated: 'Blocked vendors should not be sent to SAP S/4HANA.' The request applies to vendor creates and changes originating after interface go-live."], ["Current specification", "BR-01 in FS-INT-VM-001 requires legal name, country, language, and supplier account group/category for each create. The mapping defines several mandatory fields but does not define BlockedVendorIndicator as mandatory."], ["Conflict identified", "If a message is excluded solely because the source considers the vendor blocked, SAP receives neither a supplier record nor an auditable status event. If the blocked flag is absent or ambiguous, the interface cannot determine whether to exclude or process. This conflicts with the mandatory-data and traceability expectations in the specification."], ["Existing vendors", "The client did not confirm whether vendors already created in SAP should be blocked, flagged, or left unchanged when their source status later becomes blocked."], ["Controls", "Finance noted that vendors used for open invoices may need to remain in SAP, but purchasing should be prevented. Security requested that exclusions be logged for audit and reconciliation."]], [1.35*inch,5.65*inch])]
s += [p("Requirement Conflict Detail", "H1Blue"), tbl(["Item", "Current requirement", "Requested change", "Conflict / impact"], [["Selection rule", "No explicit status-based exclusion is specified.", "Exclude blocked vendors from outbound interface.", "Needs a reliable status field and clear timing rule."], ["Mandatory source data", "BR-01 mandates supplier account group/category; blocked status is not mandatory.", "Blocked status must drive processing decision.", "A non-mandatory status cannot support deterministic exclusion or audit."], ["Target handling", "Create/update supplier BP when valid data is supplied.", "Do not create/update blocked vendors.", "No rule exists for vendors already present in SAP."], ["Reconciliation", "All approved source changes are reconciled to SAP responses.", "Excluded messages must not be sent.", "Reconciliation must separately count and explain exclusions."]], [1.15*inch,1.85*inch,1.8*inch,2.2*inch], highlight=2)]
s += [p("Clarification Needed", "H2Blue"), p("The client must confirm whether 'blocked' means a source vendor marked blocked for purchasing, blocked for payment, inactive, pending review, or any combination. The answer determines whether exclusion is appropriate or whether SAP should receive a supplier with a purchasing/payment block.")]
s += [p("Proposed Resolution", "H1Blue"), p("Adopt a controlled status rule instead of a silent exclusion: make <b>BlockedVendorIndicator</b> mandatory in every vendor payload, require an approved status code, and route blocked vendors according to the agreed status treatment. The default proposal is: (a) do not create new blocked vendors in SAP; (b) for existing SAP suppliers, send a controlled update that applies the approved purchasing and/or payment block; (c) log every excluded or blocked message with source vendor ID, status, reason, timestamp, and correlation ID; and (d) include these records in the daily reconciliation.")]
s += [p("Required Functional Specification Changes", "H1Blue"), tbl(["Ref.", "Proposed change", "Owner", "Approval needed"], [["BR-01", "Add BlockedVendorIndicator and BlockReasonCode to the mandatory interface header for all create/change messages.", "SAP Functional Lead", "Client Data Lead"], ["BR-07 (new)", "If BlockedVendorIndicator = Y and no SAP BP exists, acknowledge as EXCLUDED_BLOCKED and do not create a supplier.", "Integration Lead", "Client Process Owner"], ["BR-08 (new)", "If BlockedVendorIndicator = Y and SAP BP exists, apply the mapped purchasing/payment block; do not delete master data.", "SAP Functional Lead", "AP Manager"], ["Mapping", "Add source status, block reason, effective date, and status-source-system to the payload mapping and reconciliation report.", "Integration Lead", "Client Data Lead"]], [.85*inch,3.8*inch,1.15*inch,1.2*inch])]
s += [p("Decision Log and Actions", "H1Blue"), tbl(["ID", "Action / decision", "Owner", "Due date", "Status"], [["D-01", "Confirm business definition of blocked vendor and status-code list.", "Client Vendor Data Lead", "22 Oct 2026", "Open"], ["D-02", "Confirm whether existing SAP suppliers receive purchasing block, payment block, or both.", "Client AP Manager", "22 Oct 2026", "Open"], ["A-01", "Update FS-INT-VM-001 after client decision; add BR-07/BR-08 and mapping fields.", "SAP Functional Lead", "2 business days after D-01/D-02", "Pending"], ["A-02", "Update integration design, error codes, and reconciliation report to record exclusions.", "Integration Lead", "After FS approval", "Pending"], ["A-03", "Add test cases for blocked new vendor, blocked existing supplier, missing status, and replay.", "Test Lead", "Before SIT", "Pending"]], [.55*inch,3.65*inch,1.15*inch,.9*inch,.75*inch])]
s += [Spacer(1,.13*inch), p("Risk Statement", "H2Blue"), p("Proceeding without the decision can create inconsistent supplier populations, bypass blocked-vendor controls, and make it impossible to prove why a source vendor was excluded. This item should be resolved before design sign-off and before interface build begins.", "Body")]
doc.build(s, onFirstPage=foot, onLaterPages=foot)
print(OUT)
